import logo from './logo.svg';
import './App.css';




import '.App.css';

function App() {
const perfumes = [
{ id: 1, nombre: 'Esencia Floral', precio: '$80.000', desc: 'Notas de jazmín y rosa' },
{ id: 2, nombre: 'Madera Noble', precio: '$95.000', desc: 'Sándalo y cedro' },
{ id: 3, nombre: 'Cítrico Fresco', precio: '$70.000', desc: 'Limón y bergamota' },
];

return (
<div className="App">
  <header className="encabezado">
    <h1>Perfumería Gustavo</h1>
    <p>Fragancias para cada momento</p>
  </header>

  <main className="catalogo">
    {perfumes.map((p) => (
    <div className="tarjeta" key={p.id}>
      <h2>{p.nombre}</h2>
      <p>{p.desc}</p>
      <strong>{p.precio}</strong>
      <button>Comprar</button>
    </div>
    ))}
  </main>

  <footer className="pie">
    <p>© 2026 Perfumería Gustavo</p>
  </footer>
</div>
);
}

export default App;
